const VIEW_BOX = { width: 262, height: 98 };
const BASE_RADIUS = 2.88;
const RADIUS_MULTIPLIER = 2.5;
const DURATION_MS = 250;

export default function InteractiveDotMatrixFooter() {
  const containerRef = useRef(null);
  const canvasRef = useRef(null);

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId = 0;
    let dots = [];
    let scaledRadius = BASE_RADIUS;

    const clearCanvas = () => {
      const dpr = window.devicePixelRatio || 1;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, container.clientWidth, container.clientHeight);
    };

    const renderDots = (now) => {
      clearCanvas();
      ctx.fillStyle = '#ffffff';
      ctx.shadowColor = 'rgba(255, 87, 34, 0.95)';
      ctx.shadowBlur = 12;
      let hasActive = false;

      for (let dot of dots) {
        if (dot.offAt > now) {
          ctx.beginPath();
          ctx.arc(dot.x, dot.y, scaledRadius, 0, Math.PI * 2);
          ctx.fill();
          hasActive = true;
        }
      }
      return hasActive;
    };

    const loop = (now) => {
      const active = renderDots(now);
      if (active) {
        animId = requestAnimationFrame(loop);
      } else {
        animId = 0;
      }
    };

    const startLoop = () => {
      if (!animId) {
        animId = requestAnimationFrame(loop);
      }
    };

    const handleResize = () => {
      const w = container.clientWidth;
      const h = container.clientHeight;
      if (w < 8 || h < 8) return;

      const dpr = window.devicePixelRatio || 1;
      const pixelW = Math.round(w * dpr);
      const pixelH = Math.round(h * dpr);

      if (canvas.width !== pixelW || canvas.height !== pixelH) {
        canvas.width = pixelW;
        canvas.height = pixelH;
      }

      const scaleX = w / VIEW_BOX.width;
      const scaleY = h / VIEW_BOX.height;
      scaledRadius = BASE_RADIUS * scaleX;

      dots = DOT_COORDINATES.map((d) => ({
        x: d.x * scaleX,
        y: d.y * scaleY,
        offAt: 0
      }));

      if (animId) cancelAnimationFrame(animId);
      animId = 0;
      clearCanvas();
    };

    const handlePointerMove = (e) => {
      if (dots.length === 0) return;
      const rect = canvas.getBoundingClientRect();
      if (rect.width === 0 || rect.height === 0) return;

      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const hitRadius = scaledRadius * 2 * RADIUS_MULTIPLIER;
      const hitRadiusSq = hitRadius * hitRadius;
      const offTime = performance.now() + DURATION_MS;

      let triggered = false;
      for (let dot of dots) {
        const dx = dot.x - mouseX;
        const dy = dot.y - mouseY;
        if (dx * dx + dy * dy < hitRadiusSq) {
          dot.offAt = offTime;
          triggered = true;
        }
      }

      if (triggered) {
        startLoop();
      }
    };

    handleResize();

    const resizeObserver = new ResizeObserver(() => {
      handleResize();
    });
    resizeObserver.observe(container);

    container.addEventListener('pointermove', handlePointerMove);
    container.addEventListener('pointerenter', handlePointerMove);

    return () => {
      if (animId) cancelAnimationFrame(animId);
      resizeObserver.disconnect();
      container.removeEventListener('pointermove', handlePointerMove);
      container.removeEventListener('pointerenter', handlePointerMove);
    };
  }, []);

  return (
    <div
      ref={containerRef}
      className="st-footer-logo"
      style={{
        position: 'relative',
        width: '100%',
        maxWidth: '1600px',
        margin: '0 auto',
        display: 'flex',
        justifyContent: 'center',
        cursor: 'default',
        userSelect: 'none'
      }}
    >
      {/* Base BRAND SCALING wordmark SVG underlay */}
      <img
        src="/assets/brand_scaling_logo.svg"
        alt="BRAND SCALING"
        className="st-footer-wordmark"
        style={{
          width: '100%',
          height: 'auto',
          display: 'block',
          pointerEvents: 'none'
        }}
      />

      {/* Interactive Canvas on Top */}
      <canvas
        ref={canvasRef}
        className="st-footer-dots"
        style={{
          position: 'absolute',
          inset: 0,
          width: '100%',
          height: '100%',
          pointerEvents: 'none'
        }}
      />
    </div>
  );
}
